const userInput = $("Webhook").first().json.body ||
  $("Webhook").first().json.query || {};
const targetDegreeRaw = (userInput.degree_type || "").toLowerCase();
const targetCourseRaw = (userInput.course || "").toLowerCase();

let targetDegree = "";
if (targetDegreeRaw.includes("master")) targetDegree = "master";
else if (targetDegreeRaw.includes("bachelor")) targetDegree = "bachelor";
else if (targetDegreeRaw.includes("single cycle")) targetDegree = "single cycle";

const stopWords = ["from", "of", "the", "in", "and", "a", "an", "at", "for", "to"];

function cleanWord(w) {
  return w.replace(/[^a-z0-9]/g, "");
}

const targetWords = targetCourseRaw
  .split(/\s+/)
  .map(cleanWord)
  .filter(w => w.length > 1 && !stopWords.includes(w));

function levenshtein(a, b) {
  const m = a.length, n = b.length;
  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (a[i - 1] === b[j - 1]) dp[i][j] = dp[i - 1][j - 1];
      else dp[i][j] = 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
    }
  }
  return dp[m][n];
}

function fuzzyMatch(word1, word2) {
  if (word1 === word2) return true;
  if (word2.includes(word1) || word1.includes(word2)) return true;
  const maxLen = Math.max(word1.length, word2.length);
  const allowedDistance = maxLen <= 4 ? 1 : maxLen <= 8 ? 2 : 3;
  return levenshtein(word1, word2) <= allowedDistance;
}

const rows = $input.all();

const scoredResults = rows.map(item => {
  const rowData = item.json;
  const courseName = (rowData['Course name'] || "").toLowerCase();
  const department = (rowData['Department'] || "").toLowerCase();
  const courseType = (rowData['Course Type'] || "").toLowerCase();

  const degreeMatch = targetDegree && courseType.includes(targetDegree);
  if (!degreeMatch) return null;

  const courseWords = courseName.split(/\s+/).map(cleanWord).filter(w => w.length > 1);
  const deptWords = department.split(/\s+/).map(cleanWord).filter(w => w.length > 1);
  const allFieldWords = [...courseWords, ...deptWords];

  let matchedWordCount = 0;
  targetWords.forEach(tw => {
    const hasMatch = allFieldWords.some(fw => fuzzyMatch(tw, fw));
    if (hasMatch) matchedWordCount++;
  });

  if (matchedWordCount === 0) return null;

  let score = matchedWordCount * 3;
  if (courseName === targetCourseRaw) score += 10;

  return { json: { ...rowData, matchScore: score } };
})
  .filter(item => item !== null)
  .sort((a, b) => b.json.matchScore - a.json.matchScore)
  .slice(0, 5);

return scoredResults;
